public class NearbyCompletionTest{public static void main(String[]a){String[] statuses={"pending","accepted","paired","paired","cancelled","declined","blocked","accepted"};boolean[] saved={false,true,false,true,false,false,false,false};long[] now={1,1,1,1,1,1,1,100};int[] want={0,0,0,1,-1,-1,-1,-1};for(int i=0;i<statuses.length;i++)if(NearbyCompletion.state(statuses[i],100,now[i],saved[i])!=want[i])throw new AssertionError(i);System.out.println("PASS8 completion state: pending/accept not success, paired requires saved peer, expiry/cancel/decline/block stop waiting");}}
